label("$y = \frac{2x^2 + 3x - 7}{x - 3}$",(5.67,-27.99),NE*lsf); label("$y = 2x + 9$",(18.43,35.5),NE*lsf);

clip((xmin,ymin)--(xmin,ymax)--(xmax,ymax)--(xmax,ymin)--cycle);

[/asy]

